css:
.loader {
  position: relative;
  width: 52px;
  height: 48px;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 4px;
  left: 50%;
  width: 4px;
  height: 34px;
  margin-left: -2px;
  border-radius: 2px;
  background: #4338ca;
}
.loader::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 24px;
  height: 5px;
  margin-left: -12px;
  border-radius: 2px;
  background: #4338ca;
}
.loader i {
  position: absolute;
  top: 8px;
  left: 50%;
  width: 40px;
  height: 4px;
  margin-left: -20px;
  border-radius: 2px;
  background: #6366f1;
  transform-origin: center;
  animation: tip 2s ease-in-out infinite;
}
.loader i::before {
  content: "";
  position: absolute;
  top: 2px;
  left: -4px;
  width: 14px;
  height: 8px;
  border: 2px solid #6366f1;
  border-top: 0;
  border-radius: 0 0 40% 40%;
  box-sizing: border-box;
}
.loader i::after {
  content: "";
  position: absolute;
  top: 2px;
  right: -4px;
  width: 14px;
  height: 8px;
  border: 2px solid #6366f1;
  border-top: 0;
  border-radius: 0 0 40% 40%;
  box-sizing: border-box;
}
@keyframes tip {
  0%, 100% { transform: rotate(-9deg); }
  50% { transform: rotate(9deg); }
}
